@js:
var reg1=/第\d+.(\d+)页/,
reg2=/page=(\d+)/,
ys=src.match(reg1);
ys=ys?ys[1]:null;
var page=baseUrl.match(reg2);
page=page?page[1]:null;
var next=[];
if(ys&&page){
	for(i=2;i<=ys;i++){
		url=baseUrl.replace(reg2,"page="+i);
		next.push(url);
		}
	}
next;

